import{_ as t,c as e,o as A,b0 as l}from"./chunks/framework.Dmsv_Tiv.js";const r="data:image/png;base64,",i="/media-docs/assets/isp_process.B92KXBUl.jpg",d="/media-docs/assets/image-20251029170329936.DKAj3PB4.png",n="data:image/png;base64,",p="data:image/png;base64,",u=JSON.parse('{"title":"LV001-概述","description":null,"frontmatter":{"title":"LV001-概述","date":"2025-10-29T14:09:58.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/camera/cam-basic/126b0f65f5de29e0bd6f65b2","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-10-29T14:09:58.670Z","fulluuid":"0bd6f65b2a124d5886968f933ab85100","useduuid":"0bd6f65b2"}},"headers":[],"relativePath":"sdoc/camera/cam-basic/126b0f65f5de29e0bd6f65b2.md","filePath":"sdoc/05-Camera/01-Camera基础/LV001-概述.md","lastUpdated":1767537778000}'),o={name:"sdoc/camera/cam-basic/126b0f65f5de29e0bd6f65b2.md"};function s(c,a,I,S,g,P){return A(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="lv001-概述" tabindex="-1">LV001-概述 <a class="header-anchor" href="#lv001-概述" aria-label="Permalink to &quot;LV001-概述&quot;">​</a></h1><p>这一部分我们来对一些常见的术语做一个基础的了解。</p><h2 id="一、一些常见的术语" tabindex="-1">一、一些常见的术语 <a class="header-anchor" href="#一、一些常见的术语" aria-label="Permalink to &quot;一、一些常见的术语&quot;">​</a></h2><p>在开发过程中会遇到一些与 sensor 相关的概念：</p><table><thead><tr><th align="center"> 术语 </th><th align="center"> 解释 </th><th> 备注 </th></tr></thead><tbody><tr><td align="center"> Camera </td><td align="center"> an optical instrument that captures a visual image.</td><td> 光学仪器捕获视觉形象显示在感光表面 </td></tr><tr><td align="center"> CCM </td><td align="center"> Camera Compact Module </td><td> 摄像头模组 </td></tr><tr><td align="center"> Image sensor </td><td align="center"> detects and conveys information used to make an image.</td><td> 两种主流传感器为 <strong> CCD </strong> 和 <strong> CMOS </strong></td></tr><tr><td align="center"> CCD </td><td align="center"> charge-coupled device </td><td> 电荷耦合 </td></tr><tr><td align="center"> CMOS </td><td align="center"> Complementary Metal-Oxide Semiconductor </td><td> 互补性氧化金属半导体 </td></tr><tr><td align="center"> pixel </td><td align="center"> 像素 </td><td> 相机传感器上的最小感光单位 </td></tr><tr><td align="center"> IR Filter </td><td align="center"> 红外滤光片 </td><td> 人眼看不到红外光，但 sensor 可，需将红外光滤掉使图像更接近人眼看到效果。</td></tr><tr><td align="center"> Lens </td><td align="center"> 镜头 </td><td> 分为塑胶透镜(plastic)或玻璃透镜(glass)</td></tr><tr><td align="center"> DSP </td><td align="center"> Digital signal processor, </td><td> 就是把 Raw RGB 格式转换成 RGB 格式或者是 YUV 格式 </td></tr><tr><td align="center"> ISP </td><td align="center"> Image signal processor, </td><td> 把 sensor 采集到的原始数据转换为显示支持 的格式 </td></tr><tr><td align="center"> 3A 算法 </td><td align="center"> AF、AE、AWB </td><td> 自动对焦、自动曝光、自动白平衡 </td></tr><tr><td align="center"> A/D 转换 </td><td align="center"> analog signals to digital format </td><td></td></tr></tbody></table><h2 id="三、isp" tabindex="-1">三、ISP <a class="header-anchor" href="#三、isp" aria-label="Permalink to &quot;三、ISP&quot;">​</a></h2><h3 id="_1-isp-简介" tabindex="-1">1. ISP 简介 <a class="header-anchor" href="#_1-isp-简介" aria-label="Permalink to &quot;1. ISP 简介&quot;">​</a></h3><p>ISP(Image Signal Processor)，即图像信号处理器，用于处理图像信号传感器输出的图像信号。它在相机系统中占有核心主导的地位，是构成相机的重要设备。</p><p>一般用来处理 Image Sensor（图像传感器）的输出数据，如做 AEC（自动曝光控制）、AGC（自动增益控制）、AWB（自动白平衡）、色彩校正、Lens Shading、Gamma 校正、祛除坏点、Auto Black Level、Auto White Level 等等功能的处理。</p><p>如下图所示，ISP 内部包含 CPU、SUP IP、IF 等设备，事实上，可以认为 ISP 是一个 SOC，可以运行各种算法程序，实时处理图像信号。</p><p><img src="'+r+'" alt="ISP 架构"></p><ul><li>CPU：即中央处理器，可以运行 AF、LSC 等各种图像处理算法，控制外围设备。现代的 ISP 内部的 CPU 一般都是 ARM Cortex-A 系列的，例如 Cortex-A5、Cortex-A7。</li><li>SUB IP：是各种功能模块的通称，对图像进行各自专业的处理。常见的 SUB IP 如 DIS、CSC、VRA 等。</li><li>图像传输接口：主要分两种，并口 ITU 和串口 CSI。CSI 是 MIPI CSI 的简称，鉴于 MIPI CSI 的诸多优点，在手机相机领域，已经广泛使用 MIPI-CSI 接口传输图像数据和各种自定义数据。外置 ISP 一般包含 MIPI-CSIS 和 MIPI-CSIM 两个接口。内置 ISP 一般只需要 MIPI-CSIS 接口。</li><li>通用外围设备：指 I2C、SPI、PWM、UART、WATCHDOG 等。ISP 中包含 I2C 控制器，用于读取 OTP 信息，控制 VCM 等。对于外置 ISP，ISP 本身还是 I2C 从设备。AP 可以通过 I2C 控制 ISP 的工作模式，获取其工作状态等。</li></ul><h3 id="_2-主要功能特性" tabindex="-1">2. 主要功能特性 <a class="header-anchor" href="#_2-主要功能特性" aria-label="Permalink to &quot;2. 主要功能特性&quot;">​</a></h3><p>ISP 作为图像处理的核心器件，拥有十分重要的功能，下图展示了 ISP 处理图像数据的基本流程。</p><p><img src="'+i+'" alt="ISP 处理流程"></p><ul><li>DEMOSAIC</li></ul><p>DEMOSAIC 是 ISP 的主要功能之一。SENSOR 的像素点上覆盖着 CFA，光线通过 CFA 后照射到像素上。CFA 由 R、G、B 三种颜色的遮光罩组成，每种遮光罩只允许一种颜色通过，因此每个像素输出的信号只包含 R、G、B 三者中的一种颜色信息。SENSOR 输出的这种数据就是 BAYER 数据，即通常所说的 RAW 数据。显而易见，RAW 数据所反映的颜色信息不是真实的颜色信息。DEMOSAIC 就是通过插值算法将将每个像素所代表的真实颜色计算出来。</p><ul><li>FOCUS</li></ul><p>根据光学知识，景物在传感器上成像最清晰时处于合焦平面上。通过更改 LENS 的位置，使得景物在传感器上清晰的成像，是 ISP FOCUS 功能所需要完成的任务。FOCUS 分为手动和自动两种模式。ISP 可以运行 CONTRAST AF、PDAF、LASER AF 等算法实现自动对焦。</p><ul><li>EXPOSURE</li></ul><p>曝光。EXPOSURE 主要影响图像的明暗程度。ISP 需要实现 AE 功能，通过控制曝光程度，使得图像亮度适宜。</p><ul><li>WB</li></ul><p>白平衡。白平衡与色温相关，用于衡量图像的色彩真实性和准确性。ISP 需要实现 AWB 功能，力求在各种复杂场景下都能精确的还原物体本来的颜色。</p><ul><li>LSC</li></ul><p>用于消除图像周边和图片中心的不一致性，包含亮度和色度两方面。ISP 需要借助 OTP 中的校准数据完成 LSC 功能。</p><ul><li>GAMMA CORRECTION</li></ul><p>伽玛校正。传感器对光线的响应和人眼对光线的响应是不同的。伽玛校正就是使得图像看起来符合人眼的特性。</p><ul><li>CROP/RESIZE</li></ul><p>图像剪裁，即改变图像的尺寸。可用于输出不同分辨率的图像。</p><ul><li>VRA</li></ul><p>视觉识别。用于识别特定的景物，例如人脸识别，车牌识别。ISP 通过各种 VRA 算法，准确的识别特定的景物。</p><ul><li>DRC</li></ul><p>动态范围校正。动态范围即图像的明暗区间。DRC 可以使得暗处的景物不至于欠曝，而亮处的景物不至于过曝。ISP 需要支持 DRC 功能。</p><ul><li>CSC</li></ul><p>颜色空间转换。例如，ISP 会将 RGB 信号转化为 YUV 信号输出。</p><ul><li>IS</li></ul><p>图像稳定。IS 的主要作用是使得图像不要因为手持时轻微的抖动而模糊不清。IS 有很多种，例如 OIS、DIS、EIS。ISP 可以实现 DIS 和 EIS。</p><p>事实上，ISP 除了上面提到的主要功能外，还需要支持 DENOISE、CONTRAST、SATURATION、SHARPNESS 等调整功能。</p><h3 id="_3-工作流程" tabindex="-1">3. 工作流程 <a class="header-anchor" href="#_3-工作流程" aria-label="Permalink to &quot;3. 工作流程&quot;">​</a></h3><p>可以参考一下《Rockchip RK3568 Technical Reference Manual》中 Fig. 12-1 ISP Block Diagram（图中每部分可以参考文档）：</p><p><img src="'+d+'" alt="image-20251029170329936"></p><p>ISP 的主要作用是对前端图像传感器输出的信号做后期处理，大致流程如下：</p><p>从传感器获取原始数据：图像传感器（通常为 CMOS 传感器&amp;CCD 传感器）首先捕捉图像的原始数据。这些数据通常是带有噪声、缺少颜色信息和对比度较低的 RAW 图像数据。</p><p>数据预处理：原始图像数据经过初步的处理，如信号放大、模数转换等，以准备进入后续的图像处理阶段。</p><p>图像处理：ISP 对原始数据进行复杂的处理，包括去噪、色彩校正、去马赛克、动态范围优化、锐化等，最终得到一张视觉效果优化的图像。</p><p>输出和显示：经过处理后的图像可以传输到显示屏，或者存储到存储介质中。</p><h3 id="_4-isp-架构方案" tabindex="-1">4. ISP 架构方案 <a class="header-anchor" href="#_4-isp-架构方案" aria-label="Permalink to &quot;4. ISP 架构方案&quot;">​</a></h3><h4 id="_4-1-外置-isp-架构" tabindex="-1">4.1 外置 ISP 架构 <a class="header-anchor" href="#_4-1-外置-isp-架构" aria-label="Permalink to &quot;4.1 外置 ISP 架构&quot;">​</a></h4><p>外置 ISP 架构是指在 AP 外部单独布置 ISP 芯片用于图像信号处理。外置 ISP 的架构图一般如下所示：</p><p><img src="'+n+'" alt="外置 ISP 架构图"></p><p>外置 ISP 架构的优点主要有：</p><ul><li>能够提供更优秀的图像质量</li></ul><p>在激烈的市场竞争下，能够存活到现在的外置 ISP 生产厂商在此领域一般都有很深的造诣，积累了丰富的影像质量调试经验，能够提供比内置 ISP 更优秀的性能和效果。因此，选用优质的外置 ISP 能提供专业而且优秀的图像质量。</p><ul><li>能够支援更丰富的设计规划</li></ul><p>外置 ISP 的选型基本不受 AP 的影响，因此魅族可以从各个优秀 ISP 芯片供应商的众多产品中甄选最合适的器件，从而设计出更多优秀的产品。</p><ul><li>能够实现产品的差异化</li></ul><p>内置 ISP 是封装在 AP 内部的，是和 AP 紧密的联系在一起，如果 AP 相同，那么 ISP 也就是一样的。因此基于同样 AP 生产出来的手机，其 ISP 的性能也是一样的，可供调教的条件也是固定的，这样就不利于实现产品的差异化。而如果选择外置 ISP，那么同一颗 AP，可以搭配不同型号的 ISP，这样可以实现产品的差异化，为给用户提供更丰富和优质的产品。</p><p>外置 ISP 架构的缺点主要有：</p><ul><li>成本价格高</li></ul><p>外置 ISP 需要单独购买，其售价往往不菲，而且某些特殊功能还需要额外支付费用。使用外置 ISP，需要进行额外的原理图设计和 LAYOUT，需要使用额外的元器件。</p><ul><li>开发周期长</li></ul><p>外置 ISP 驱动的设计需要多费精力和时间。使用外置 ISP 时，AP 供应商提供的 ISP 驱动就无法使用，需要额外设计编写外置 ISP 驱动。另外，为了和 AP 进行完美的搭配，将效果最大化，也往往需要付出更多的调试精力。上文也提到，使用外置 ISP，需要进行额外的原理图设计和 LAYOUT，需要使用额外的元器件，这也是需要花费时间进行处理的。</p><h4 id="_4-2-内置-isp-架构" tabindex="-1">4.2 内置 ISP 架构 <a class="header-anchor" href="#_4-2-内置-isp-架构" aria-label="Permalink to &quot;4.2 内置 ISP 架构&quot;">​</a></h4><p>内置 ISP 架构是指在 AP 内部嵌入了 ISP IP，直接使用 AP 内部的 ISP 进行图像信号处理。内置 ISP 的架构图一般如下所示：</p><p><img src="'+p+'" alt="内置 ISP 架构图"></p><p>内置 ISP 架构的优点主要有：</p><ul><li>能降低成本价格</li></ul><p>内置 ISP 内嵌在 AP 内部，因此无需像外置 ISP 一样需要额外购买，且不占 PCB 空间，无需单独为其设计外围电路，这样就能节省 BOM，降低成本。鉴于大多数用户在选购手机时会将价格因素放在重要的位置，因此降低成本能有效的降低终端成品价格，有利于占领市场。</p><ul><li>能提高产品的上市速度</li></ul><p>内置 ISP 和 AP 紧密结合，无需进行原理图设计和 LAYOUT 设计，因此可以减小开发周期，加快产品上市的速度。</p><ul><li>能降低开发难度</li></ul><p>如果使用内置 ISP，那么 AP 供应商能在前期提供相关资料，驱动开发人员可以有充足的时间熟悉相关资料，而且不会存在软件版本适配问题，也不存在平台架构兼容性问题。但是，如果使用外置 ISP，那么 ISP 供应商往往都不能提供针对某个平台的代码/资料，而且一般都存在软件版本兼容问题，这就需要驱动开发人员付出额的经历和时间。</p><h3 id="_5-3a-算法" tabindex="-1">5. 3A 算法 <a class="header-anchor" href="#_5-3a-算法" aria-label="Permalink to &quot;5. 3A 算法&quot;">​</a></h3><p>3A 即自动对焦（AF）、自动曝光（AE）和自动白平衡（AWB），3A 数字成像技术利用了 AF、AE、AWB 算法实现图像对比度最大、改善目标拍摄物过曝光或曝光不足情况，使画面在不同光线照射下的色差得到补偿，从而呈现较高画质的图像信息。</p><blockquote><p>参考资料：</p><p><a href="https://blog.csdn.net/Scott_S/article/details/118525159" target="_blank" rel="noreferrer">【Camera】Camera 理论知识和基本原理-CSDN 博客</a></p><p><a href="https://blog.csdn.net/baidu_38797690/article/details/126087923" target="_blank" rel="noreferrer">Camera 简介(一)：摄像头模组 CCM 的结构和原理简述_手机摄像模组介绍-CSDN 博客</a></p><p><a href="https://blog.csdn.net/wss794/article/details/142357160" target="_blank" rel="noreferrer">【Camera】摄像头模组 CCM 、工作原理以及 3A 算法-CSDN 博客</a></p><p><a href="https://zhuanlan.zhihu.com/p/100777121" target="_blank" rel="noreferrer">(3 封私信) Understanding CMOS Image Sensor - 知乎</a></p><p><a href="https://mp.weixin.qq.com/s/UanwwJAPuJGXZCiuZ-QoSQ" target="_blank" rel="noreferrer">5 分钟理解相机 ISP (图像信号处理)</a></p><p><a href="https://kernel.meizu.com/2016/06/05/camera-isp-intro.html/" target="_blank" rel="noreferrer">相机系统综述 —— ISP - 魅族内核团队</a></p><p><a href="https://cloud.tencent.com/developer/article/2016190" target="_blank" rel="noreferrer">ISP 算法及架构分析介绍-腾讯云开发者社区-腾讯云</a></p></blockquote>',75)])])}const E=t(o,[["render",s]]);export{u as __pageData,E as default};
